-- L30-l1-anime-bank-lot2.sql (run O1, lane animebank, lot 2; generated by apps/quiz/e2e/o1/L1/anime-bank-lot2-sql.mjs, do not edit by hand)
--
-- What:   files 30 of the 58 L08 anime drafts left after lot 1 (L29) as verified, scheduled daily quizzes, one a day from 2026-12-19 to 2027-01-17. Almost every draft question repeated a fact
--         already asked, so the quizzes are rebuilt on new sourced questions (each re-read at a pinned Wikipedia revision, three readings: docs/anime/data/verify/bank-lot2.json, bank-lot2.md).
--         Per row: title, description, questions, status 'scheduled', scheduled_date, verified_at = now(), verification_notes. Nothing else: no group, no other row, no kpop row.
-- Needs:  L08 (the draft rows) and L29 (lot 1 filed 2026-11-21 to 2026-12-18). This is data only: it can be applied before the code of the final merge. The owner fills {REVIEWER} and {REVIEW_DATE}
--         (two constants at the top of the block) after the review: while they are unfilled the file refuses to apply.
-- WHEN:   after a backup, outside a build, never between 23:50 and 00:30 UTC, well before 2026-12-17 (the anime daily would otherwise run out after 2026-12-18).
-- Refuses: while the review constants are unfilled; if any anime row already has a scheduled_date from 2026-12-19 to 2027-01-17 (other than these rows in their final state); if a row is no longer in its exact L08 state
--         (status draft, no date, not verified, not published, same questions); the self-check raises unless exactly 30 rows changed (a second run changes none). One DO block, so a raise applies nothing.
-- Verify: select count(*) from public.quiz_bank where site_id = 'anime' and status = 'scheduled' and scheduled_date between '2026-12-19' and '2027-01-17' and verified_at is not null and published_quiz_id is null;   expect 30
-- Verify: select count(*) from public.quiz_bank where site_id = 'anime' and scheduled_date between '2026-12-19' and '2027-01-17' and verification_notes like '%(L30)%' and jsonb_array_length(questions) = 8;   expect 30
-- Verify: select count(*) from public.quiz_bank where site_id = 'anime' and scheduled_date = '2026-12-19' and title = 'Death Note on Screen, Stage and Console';   expect 1
-- Verify: select count(*) from public.quiz_bank where site_id = 'anime' and scheduled_date = '2027-01-17' and title = 'Name the Series: Songs First';   expect 1
-- Verify: select count(*) from public.quiz_bank where site_id = 'anime' and status = 'draft' and scheduled_date is null and title in ('Which Studio Made It? True or False', 'Who Am I? Heroes, Hunters and a Rubber Body', 'Name That Series: The Big Names', 'Opening Act: Who Sang It?', 'Odd One Out: Studios, Seasons and Origins', 'Weekly Jump or Not? True or False', 'Who Am I? Elves, Idols and a Telepath', 'Odd One Out: Magazines and Publishers', 'Name That Series: Recent Favourites', 'Studio Lineup: Which Series Did They Animate?', 'Who Am I? Sleepers, Soldiers and a Strongest Sorcerer', 'Behind the Score: Who Wrote the Music?', 'In the Director''s Chair: Which Series?', 'Who Sang It? True or False', 'Odd One Out: Songs, Singers and Films', 'Name That Series: Webtoons, Novels and More', 'Sound Check: Music Trivia Across the Shelf', 'Who Publishes It? Magazines and Companies', 'Name That Series: Prizes, Films and Page Counts', 'Who Sang It? Songs Across the Shelf', 'Who Draws It? Creators and Their Manga', 'Trophy Shelf: Awards True or False', 'Name That Series: Sharper Clues', 'In the Studio: Directors and Companies', 'Odd One Out: Episodes, Networks and Studios', 'Who Am I? Boars, Bounty Hunters and a Monkey King', 'Name That Series: Big Names, New Clues', 'Calendar Check: True or False');   expect 28 (the 58 drafts left after lot 1, less the 30 filed here)
-- Verify: select count(*) from public.quiz_bank where site_id = 'anime' and scheduled_date between '2026-11-21' and '2026-12-18';   expect 28 (lot 1 and the moved row, untouched)
-- Undo:   L30-l1-anime-bank-lot2.rollback.sql (exact L08 values back, refused once one of these rows is published).
-- o1-transaction: single (psql --single-transaction). Idempotent: a second run changes nothing.

do $o1l$
declare
  v_reviewer text := '{REVIEWER}';
  v_review_date text := '{REVIEW_DATE}';
  v_rows jsonb := $o1q$[{"l08_title":"A Notebook, an Apple and a Rule","title":"Death Note on Screen, Stage and Console","description":"Eight questions on the films, drama, musical, game and awards around Death Note.","date":"2026-12-19","notes":"Sources: https://en.wikipedia.org/wiki/Death_Note (rev 1381769893) ; https://en.wikipedia.org/wiki/List_of_Death_Note_characters (rev 1384673220). Anime daily bank lot 2 (L30). Each question re-read on 2026-11-09 against its cited Wikipedia page at a pinned revision, see docs/anime/data/verify/bank-lot2.json and bank-lot2.md; three independent readings recorded there; owner review packet docs/anime/editorial/packets/bank-lot2.html. Drafted with AI assistance, checked by ","questions":[{"question":"Who directed the first two live-action Death Note films from 2006?","options":["Takashi Miike","Shusuke Kaneko","Hideo Nakata","Kiyoshi Kurosawa"],"correct":1,"kind":"production","spoiler":{"arc":0,"scope":"both"},"fact_ids":[],"source_url":"https://en.wikipedia.org/wiki/Death_Note"},{"question":"Which Broadway composer wrote the music for Death Note: The Musical?","options":["Jack Murphy","Ivan Menchell","Nick Winston","Frank Wildhorn"],"correct":3,"kind":"production","spoiler":{"arc":0,"scope":"both"},"fact_ids":[],"source_url":"https://en.wikipedia.org/wiki/Death_Note"},{"question":"Which award did the Death Note manga win in 2008 as Favourite Manga, as voted by UK fans?","options":["Seiun Award","Tezuka Osamu Cultural Prize","Eagle Award","Eisner Award"],"correct":2,"kind":"award","spoiler":{"arc":0,"scope":"both"},"fact_ids":[],"source_url":"https://en.wikipedia.org/wiki/Death_Note"},{"question":"Which company developed and published the 2007 Nintendo DS game Death Note: Kira Game?","options":["Capcom","Sega","Konami","Square Enix"],"correct":2,"kind":"production","spoiler":{"arc":0,"scope":"both"},"fact_ids":[],"source_url":"https://en.wikipedia.org/wiki/Death_Note"},{"question":"Who directed the American Death Note film rel