608) ; https://en.wikipedia.org/wiki/Gurren_Lagann (rev 1382761580) ; https://en.wikipedia.org/wiki/Noragami (rev 1377344372) ; https://en.wikipedia.org/wiki/Akame_ga_Kill! (rev 1379732409) ; https://en.wikipedia.org/wiki/Your_Lie_in_April (rev 1383941761) ; https://en.wikipedia.org/wiki/Erased_(manga) (rev 1378514957) ; https://en.wikipedia.org/wiki/KonoSuba (rev 1384421829) ; https://en.wikipedia.org/wiki/No_Game_No_Life (rev 1383872134). Anime daily bank lot 2 (L30). Each question re-read on 2026-11-09 against its cited Wikipedia page at a pinned revision, see docs/anime/data/verify/bank-lot2.json and bank-lot2.md; three independent readings recorded there; owner review packet docs/anime/editorial/packets/bank-lot2.html. Drafted with AI assistance, checked by ","questions":[{"question":"Which series has Seishun Satsubatsu-ron as its first opening theme?","options":["Gintama","Assassination Classroom","Haikyu!!","Beelzebub"],"correct":1,"kind":"music","spoiler":{"arc":0,"scope":"both"},"fact_ids":[],"source_url":"https://en.wikipedia.org/wiki/Assassination_Classroom"},{"question":"Which series opens with Sorairo Days, sung by Shoko Nakagawa?","options":["Code Geass","Kill la Kill","Eureka Seven","Gurren Lagann"],"correct":3,"kind":"music","spoiler":{"arc":0,"scope":"both"},"fact_ids":[],"source_url":"https://en.wikipedia.org/wiki/Gurren_Lagann"},{"question":"Which series opens with Goya no Machiawase, by Hello Sleepwalkers?","options":["Noragami","Blue Exorcist","Bungo Stray Dogs","Durarara!!"],"correct":0,"kind":"music","spoiler":{"arc":0,"scope":"both"},"fact_ids":[],"source_url":"https://en.wikipedia.org/wiki/Noragami"},{"question":"Which series opens its first episodes with Skyreach, sung by Sora Amamiya?","options":["Tokyo Ghoul","Psycho-Pass","Akame ga Kill!","Parasyte"],"correct":2,"kind":"music","spoiler":{"arc":0,"scope":"both"},"fact_ids":[],"source_url":"https://en.wikipedia.org/wiki/Akame_ga_Kill!"},{"question":"Which series has Hikaru Nara, by Goose House, as its first opening song?","options":["Clannad","Anohana","Violet Evergarden","Your Lie in April"],"correct":3,"kind":"music","spoiler":{"arc":0,"scope":"both"},"fact_ids":[],"source_url":"https://en.wikipedia.org/wiki/Your_Lie_in_April"},{"question":"Which series opens with Re:Re:, performed by Asian Kung-Fu Generation?","options":["Erased","Steins;Gate","Death Note","Mirai Nikki"],"correct":0,"kind":"music","spoiler":{"arc":0,"scope":"both"},"fact_ids":[],"source_url":"https://en.wikipedia.org/wiki/Erased_(manga)"},{"question":"Which series has Fantastic Dreamer, by Machico, as its first season opening?","options":["Overlord","Re:Zero","KonoSuba","Mushoku Tensei"],"correct":2,"kind":"music","spoiler":{"arc":0,"scope":"both"},"fact_ids":[],"source_url":"https://en.wikipedia.org/wiki/KonoSuba"},{"question":"Which series has This Game, by Konomi Suzuki, as its opening theme?","options":["Sword Art Online","No Game No Life","Date A Live","Sonic Boom"],"correct":1,"kind":"music","spoiler":{"arc":0,"scope":"both"},"fact_ids":[],"source_url":"https://en.wikipedia.org/wiki/No_Game_No_Life"}],"old_questions":[{"question":"Which series opens with Tank!?","options":["Fullmetal Alchemist","Neon Genesis Evangelion","Death Note","Cowboy Bebop"],"correct":3,"kind":"music","spoiler":{"arc":0,"scope":"both"},"fact_ids":["cowboy-bebop-opening-tank-009"],"source_url":"https://en.wikipedia.org/wiki/Music_of_Cowboy_Bebop"},{"question":"Which series has Kick Back by Kenshi Yonezu as its opening?","options":["Chainsaw Man","Jujutsu Kaisen","Dandadan","My Hero Academia"],"correct":0,"kind":"music","spoiler":{"arc":0,"scope":"both"},"fact_ids":["chainsaw-man-opening-theme-015"],"source_url":"https://en.wikipedia.org/wiki/Chainsaw_Man_(TV_series)"},{"question":"Which series opens its first season with Otonoke?","options":["Dandadan","Oshi no Ko","Blue Lock","Solo Leveling"],"correct":0,"kind":"music","spoiler":{"arc":0,"scope":"both"},"fact_ids":["dandadan-themes-season-one-013"],"source_url":"https://en.wikipedia.org/wiki/List_of_Dandadan_episodes"},{"question":"Which series opened its second anime with Hero's Come Back!!?","options":["Naruto","Dragon Ball","Bleach","One Piece"],"correct":0,"kind":"music","spoiler":{"arc":0,"scope":"both"},"fact_ids":["naruto-first-shippuden-opening-027"],"source_url":"https://ja.wikipedia.org/wiki/NARUTO_-%E3%83%8A%E3%83%AB%E3%83%88-_%E7%96%BE%E9%A2%A8%E4%BC%9D"},{"question":"Which franchise has Cha-La Head-Cha-La as the second opening of its run?","options":["Bleach","Dragon Ball","Naruto","One Piece"],"correct":1,"kind":"music","spoiler":{"arc":0,"scope":"both"},"fact_ids":["dragon-ball-z-theme-songs-008"],"source_url":"https://en.wikipedia.org/wiki/Dragon_Ball_Z"},{"question":"Which series used Peace Sign by Kenshi Yonezu as an opening?","options":["My Hero Academia","Demon Slayer","Haikyu!!","Chainsaw Man"],"correct":0,"kind":"music","spoiler":{"arc":0,"scope":"both"},"fact_ids":["my-hero-academia-opening-themes-011"],"source_url":"https://en.wikipedia.org/wiki/My_Hero_Academia_(TV_series)"},{"question":"Which series opened its first season with Kaikai Kitan?","options":["Chainsaw Man","Demon Slayer","Attack on Titan","Jujutsu Kaisen"],"correct":3,"kind":"music","spoiler":{"arc":0,"scope":"both"},"fact_ids":["jujutsu-kaisen-opening-themes-004"],"source_url":"https://en.wikipedia.org/wiki/Jujutsu_Kaisen_(TV_series)"},{"question":"Which anime features songs by Stray Kids in its first season?","options":["Tower of God","Blue Lock","Vinland Saga","Solo Leveling"],"correct":0,"kind":"music","spoiler":{"arc":0,"scope":"both"},"fact_ids":["tower-of-god-themes-season-one-011"],"source_url":"https://en.wikipedia.org/wiki/Tower_of_God_season_1"}]}]$o1q$::jsonb;
  r jsonb;
  n int := 0;
  step int;
  applied int;
begin
  perform set_config('lock_timeout', '5s', true);
  if v_reviewer ~ '[{](REVIEWER|REVIEW_DATE)[}]' or v_review_date ~ '[{](REVIEWER|REVIEW_DATE)[}]' then
    raise exception 'L30: review not recorded (replace {REVIEWER} and {REVIEW_DATE} at the top of the block), nothing applied';
  end if;
  if not exists (select 1 from information_schema.columns where table_schema = 'public' and table_name = 'quiz_bank' and column_name = 'site_id') then
    raise exception 'L30: quiz_bank.site_id is missing (apply 002a first)';
  end if;
  if not exists (select 1 from pg_indexes where schemaname = 'public' and indexname = 'quiz_bank_site_date') then
    raise exception 'L30: quiz_bank_site_date is missing (apply 009 and 010 first)';
  end if;

  -- Refuse if another anime row already holds a date of the lot (a lot row already in its final place does not count).
  if exists (
    select 1 from public.quiz_bank b
    where b.site_id = 'anime' and b.scheduled_date between '2026-12-19' and '2027-01-17'
      and not exists (select 1 from jsonb_array_elements(v_rows) e where lower(btrim(b.title)) = lower(btrim(e->>'title')) and b.scheduled_date = (e->>'date')::date)
  ) then
    raise exception 'L30: another anime row already has a scheduled_date between 2026-12-19 and 2027-01-17, nothing applied';
  end if;

  -- The 30 lot rows, only while still in their exact L08 state.
  for r in select e from jsonb_array_elements(v_rows) e loop
    update public.quiz_bank b set
      title = r->>'title', description = r->>'description', questions = r->'questions', status = 'scheduled', scheduled_date = (r->>'date')::date,
      verified_at = now(), verification_notes = (r->>'notes') || v_reviewer || ' on ' || v_review_date || '.', updated_at = now()
    where b.site_id = 'anime' and lower(btrim(b.title)) = lower(btrim(r->>'l08_title'))
      and b.status = 'draft' and b.scheduled_date is null and b.verified_at is null and b.published_quiz_id is null and b.questions = (r->'old_questions');
    get diagnostics step = row_count;
    n := n + step;
  end loop;

  select count(*) into applied from jsonb_array_elements(v_rows) e join public.quiz_bank b on lower(btrim(b.title)) = lower(btrim(e->>'title'))
    where b.site_id = 'anime' and b.status = 'scheduled' and b.scheduled_date = (e->>'date')::date and b.questions = (e->'questions') and b.published_quiz_id is null;

  -- Self-check: exactly 30 rows changed (or a second run: none), and every lot row is in its final state.
  if not (n in (0, 30)) or applied <> 30 then
    raise exception 'L30 self-check failed: % rows changed (expected 30 or 0), % in final state (expected 30); a row changed since L08 or published, nothing applied', n, applied;
  end if;
end $o1l$;
